import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";

const PROD_ORIGINS = [
  "https://igreen.cloud",
  "https://www.igreen.cloud",
];

const DEV_FALLBACK_ORIGINS = [
  "http://localhost:5173",
  "http://localhost:3000",
  "http://localhost:8080",
];

const BASE_ALLOW_HEADERS = "authorization, x-client-info, apikey, content-type";

function allowedOrigins(): string[] {
  const raw = Deno.env.get("ALLOWED_ORIGINS") ?? "";
  const list = raw.split(",").map((s) => s.trim()).filter(Boolean);


  return Array.from(new Set([...PROD_ORIGINS, ...list, ...DEV_FALLBACK_ORIGINS]));
}

const ORIGIN_PATTERNS: RegExp[] = [
  /^https:\/\/([a-z0-9-]+\.)*lovable\.app$/i,
  /^https:\/\/([a-z0-9-]+\.)*lovableproject\.com$/i,
  /^https:\/\/([a-z0-9-]+\.)*lovable\.dev$/i,
];

function isOriginAllowed(origin: string, allow: string[]): boolean {
  if (!origin) return false;
  if (allow.includes(origin)) return true;
  return ORIGIN_PATTERNS.some((re) => re.test(origin));
}

function buildCors(req: Request, extraAllowHeaders = ""): Record<string, string> {
  const origin = req.headers.get("Origin") ?? "";
  const allow = allowedOrigins();


  const allowOrigin = isOriginAllowed(origin, allow) ? origin : allow[0];

  return {
    "Access-Control-Allow-Origin": allowOrigin,
    "Access-Control-Allow-Headers": extraAllowHeaders
      ? `${BASE_ALLOW_HEADERS}, ${extraAllowHeaders}`
      : BASE_ALLOW_HEADERS,
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Vary": "Origin",
  };
}

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-service-secret",
};

type Caller =
  | { mode: "jwt"; consultantId: string; isAdmin: boolean }
  | { mode: "service" };

function jsonResponse(status: number, body: Record<string, unknown>): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function timingSafeEqual(a: string, b: string): boolean {
  const enc = new TextEncoder();
  const aBytes = enc.encode(a);
  const bBytes = enc.encode(b);

  let diff = aBytes.length ^ bBytes.length;
  const len = Math.max(aBytes.length, bBytes.length);
  for (let i = 0; i < len; i++) {
    const av = i < aBytes.length ? aBytes[i] : 0;
    const bv = i < bBytes.length ? bBytes[i] : 0;
    diff |= av ^ bv;
  }
  return diff === 0;
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function isValidUuid(value: unknown): value is string {
  return typeof value === "string" && UUID_RE.test(value);
}

async function resolveCaller(
  req: Request,
  admin: SupabaseClient,
): Promise<Caller | Response> {

  const serviceSecret = Deno.env.get("SERVICE_SHARED_SECRET") ?? "";
  const headerSecret = req.headers.get("x-service-secret");
  if (serviceSecret.length > 0 && headerSecret !== null) {
    if (timingSafeEqual(headerSecret, serviceSecret)) {
      return { mode: "service" };
    }
  }


  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.startsWith("Bearer ")
    ? authHeader.slice("Bearer ".length).trim()
    : "";
  if (token.length > 0) {
    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const anonKey = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
    if (supabaseUrl && anonKey) {
      const anonClient = createClient(supabaseUrl, anonKey, {
        auth: { persistSession: false, autoRefreshToken: false },
      });
      const { data, error } = await anonClient.auth.getUser(token);
      const user = data?.user;
      if (!error && user?.id) {

        let isAdmin = false;
        try {
          const { data: roleData } = await admin.rpc("has_role", {
            _user_id: user.id,
            _role: "admin",
          });
          isAdmin = roleData === true;
        } catch {
          isAdmin = false;
        }
        return { mode: "jwt", consultantId: user.id, isAdmin };
      }
    }
  }


  return jsonResponse(401, { error: "unauthorized" });
}

async function assertOwnership(
  caller: Caller,
  target: { consultantId?: string; customerId?: string },
  admin: SupabaseClient,
): Promise<null | Response> {

  if (caller.mode === "service") return null;


  if (caller.isAdmin) return null;


  if (target.customerId !== undefined) {
    if (!isValidUuid(target.customerId)) {
      return jsonResponse(400, { error: "invalid_request" });
    }
    const { data, error } = await admin
      .from("customers")
      .select("consultant_id")
      .eq("id", target.customerId)
      .maybeSingle();

    if (error || !data) {
      return jsonResponse(400, { error: "invalid_request" });
    }
    if ((data as { consultant_id: string | null }).consultant_id !== caller.consultantId) {
      return jsonResponse(403, { error: "forbidden" });
    }
    return null;
  }


  if (target.consultantId !== undefined) {
    if (!isValidUuid(target.consultantId)) {
      return jsonResponse(400, { error: "invalid_request" });
    }
    if (target.consultantId !== caller.consultantId) {
      return jsonResponse(403, { error: "forbidden" });
    }
    return null;
  }


  return jsonResponse(400, { error: "invalid_request" });
}

const VELIP_BASE = "https://vox.velip.com.br/api/v2";
const VELIP_IPS = new Set(["35.232.103.91", "35.184.30.236"]);

function velipConfigured(): boolean {
  return !!Deno.env.get("VELIP_API_TOKEN")?.trim();
}

function velipWebhookAuthConfigured(): boolean {
  return !!Deno.env.get("VELIP_WEBHOOK_AUTH")?.trim();
}

function getVelipToken(): string {
  return (Deno.env.get("VELIP_API_TOKEN") ?? "").trim();
}

function getVelipWebhookAuth(): string {
  return (Deno.env.get("VELIP_WEBHOOK_AUTH") ?? "").trim();
}

function velipWebhookAuthQuery(): string {
  const t = getVelipWebhookAuth();
  return t ? `&auth=${encodeURIComponent(t)}` : "";
}

function isVelipCallerIp(ip: string | null | undefined): boolean {
  if (!ip) return false;
  return VELIP_IPS.has(ip.trim());
}

function digitsOnly(raw: string | null | undefined): string {
  return String(raw ?? "").replace(/\D/g, "");
}

function toVelipBRDest(raw: string | null | undefined): string | null {
  let d = digitsOnly(raw);
  if (!d) return null;
  if (d.startsWith("55") && (d.length === 12 || d.length === 13)) return d;
  if (d.length === 10 || d.length === 11) return `55${d}`;
  if (d.length > 13) d = d.slice(-13);
  if (d.startsWith("55") && d.length >= 12) return d;
  if (d.length >= 10 && d.length <= 11) return `55${d}`;
  return null;
}

function toCtid(id: string): string {
  return String(id || "").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 15);
}

function velipHeaders(extra: Record<string, string> = {}): Record<string, string> {
  return {
    Authorization: `Bearer ${getVelipToken()}`,
    Accept: "application/json",
    ...extra,
  };
}

interface RawResp {
  ok: boolean;
  status_code?: number;
  status?: string;
  raw?: unknown;
  error?: string;
}

function velipEnvelope(json: Record<string, unknown>): Record<string, unknown> {
  const ret = json?.return;
  return ret && typeof ret === "object" ? (ret as Record<string, unknown>) : json;
}

function normalizeVelipStatus(raw: unknown): string | undefined {
  if (typeof raw === "string" && raw.trim()) return raw.trim();
  if (Array.isArray(raw) && raw.length > 0) {
    const first = raw[0];
    return typeof first === "string" ? first : String(first ?? "");
  }
  if (raw && typeof raw === "object") {
    const o = raw as Record<string, unknown>;
    const v = o["0"] ?? o.status ?? Object.values(o)[0];
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return undefined;
}

async function velipPost(
  path: string,
  form: URLSearchParams | FormData,
  timeoutMs = 20_000,
): Promise<RawResp> {
  const headers = velipHeaders();
  if (form instanceof URLSearchParams) {
    headers["Content-Type"] = "application/x-www-form-urlencoded; charset=UTF-8";
  }
  try {
    const res = await fetch(`${VELIP_BASE}${path}`, {
      method: "POST",
      headers,
      body: form,
      signal: AbortSignal.timeout(timeoutMs),
    });
    const text = await res.text();
    let json: Record<string, unknown> = {};
    try {
      json = text ? JSON.parse(text) : {};
    } catch {
      json = { _raw: text };
    }


    const env = velipEnvelope(json);
    const scRaw = env.status_code ?? json.status_code;
    const status_code = typeof scRaw === "number" ? scRaw : Number(scRaw ?? NaN);
    const status = normalizeVelipStatus(env.status) ?? normalizeVelipStatus(json.status);
    const ok = res.ok && (Number.isFinite(status_code) ? status_code === 0 : true);
    return {
      ok,
      status_code: Number.isFinite(status_code) ? status_code : undefined,
      status,
      raw: json,
      error: ok
        ? undefined
        : (status ?? `http_${res.status}`) +
          (Number.isFinite(status_code) ? `#${status_code}` : ""),
    };
  } catch (e) {
    return { ok: false, error: (e as Error)?.message || "network_error" };
  }
}

interface UserIDResp extends RawResp {
  saldo?: number | null;
}

async function getUserID(): Promise<UserIDResp> {
  const r = await velipPost("/GetUserID", new URLSearchParams(), 10_000);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const saldoRaw = env.saldo ?? env.balance ?? env.credit;
  const saldo = saldoRaw == null ? NaN : Number(saldoRaw);
  return { ...r, saldo: Number.isFinite(saldo) ? saldo : null };
}

interface UploadAudioResp extends RawResp {
  audio_id?: string;
}

async function uploadAudioFile(
  bytes: Uint8Array,
  name: string,
  contentType = "audio/mpeg",
): Promise<UploadAudioResp> {
  const fd = new FormData();


  const blob = new Blob([bytes as unknown as BlobPart], { type: contentType });
  const safeName = (name || "clipe").replace(/[^\w.-]+/g, "_").slice(0, 60) || "clipe";



  fd.append("audio", blob, `${safeName}.mp3`);
  fd.append("name", safeName);
  fd.append("name_up", `${safeName}.mp3`);
  fd.append("ttswrt", "1");
  const r = await velipPost("/CreateAudioFile", fd, 60_000);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const audio_id = String(
    env.cdw_file ?? env.audio_id ?? env.id ?? env.aid ?? env.audio ?? "",
  ) || undefined;
  return { ...r, audio_id };
}

interface AudioListItem {
  audio_id: string;
  name?: string;
  duration_sec?: number;
}

async function listAudios(): Promise<{ ok: boolean; items: AudioListItem[]; error?: string; raw?: unknown }> {
  const r = await velipPost("/GetAudiosList", new URLSearchParams(), 15_000);
  const raw = (r.raw ?? {}) as Record<string, unknown>;


  const arr = (raw.audios ?? raw.data ?? raw.list ?? []) as unknown[];
  const items: AudioListItem[] = [];
  if (Array.isArray(arr)) {
    for (const it of arr) {
      const row = it as Record<string, unknown>;
      const id = String(row.cdw_file ?? row.audio_id ?? row.id ?? "");
      if (!id) continue;
      items.push({
        audio_id: id,
        name: (row.cdw_name as string) ?? (row.name as string) ?? (row.nome as string) ?? undefined,
        duration_sec: Number(row.cdw_sec ?? row.duration_sec ?? row.duracao ?? NaN) || undefined,
      });
    }
  }
  return { ok: r.ok, items, error: r.error, raw };
}

interface MakeCallOpts {
  to: string;
  audioId?: string;
  ttsText?: string;

  voice?: string;
  ctid: string;
  timeLimitSec?: number;

  scheduledAt?: string;
  callerId?: string;

  free?: boolean;
}

interface MakeCallResult extends RawResp {
  cd_id?: string;
}

function baseCallForm(opts: MakeCallOpts): URLSearchParams {
  const form = new URLSearchParams();
  form.set("dest", opts.to);
  form.set("ctid", toCtid(opts.ctid));

  if (opts.timeLimitSec) form.set("timelimit", String(opts.timeLimitSec));
  if (opts.scheduledAt) form.set("block", opts.scheduledAt);
  const bina = opts.callerId ?? Deno.env.get("VELIP_CALLER_ID")?.trim();
  if (bina) form.set("callerid", bina);
  if (opts.free) form.set("free", "1");
  return form;
}

async function playAudioFile(opts: MakeCallOpts): Promise<MakeCallResult> {
  if (!opts.audioId) return { ok: false, error: "missing_audio_id" };
  return await makeTTSCall(opts);
}

async function makeTTSCall(opts: MakeCallOpts): Promise<MakeCallResult> {
  const form = baseCallForm(opts);
  if (opts.audioId) {



    const id = String(opts.audioId).trim();
    form.set("content", /^\d+$/.test(id) ? `tf${id}` : id);
  }
  if (opts.ttsText) {
    form.set("text", opts.ttsText);

    form.set("encoding", "UTF-8");
    if (opts.voice) form.set("voice", opts.voice);
  }
  const r = await velipPost("/MakeTTSCall", form);


  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const cd_id = String(env.cd_id ?? env.id ?? env.call_id ?? "") || undefined;
  return { ...r, cd_id: cd_id === "0" ? undefined : cd_id };
}

interface DestinationItem {
  dest: string;
  ctid?: string;
  name?: string;
  cod_cli?: string;
  extras?: string[];
}

interface DestinationBaseResp extends RawResp {
  base_id?: string;
}

async function createDestinationBase(
  items: DestinationItem[],
  name = `base_${Date.now()}`,
): Promise<DestinationBaseResp> {
  const form = new URLSearchParams();
  form.set("name", name);


  form.set("datajson", JSON.stringify(items.map((it) => {
    const rec: Record<string, unknown> = { phone: it.dest };
    if (it.name) rec.name = it.name;
    if (it.cod_cli) rec.cod_cli = it.cod_cli;
    (it.extras ?? []).slice(0, 4).forEach((v, i) => {
      if (v) rec[`extra${i + 1}`] = v;
    });
    return rec;
  })));
  const r = await velipPost("/CreateDestinationBase", form, 60_000);

  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const base_id = String(env.cdlc_id ?? env.base_id ?? env.id ?? "") || undefined;
  return { ...r, base_id };
}

interface CreateCampaignOpts {
  baseId: string;
  audioId: string;
  name: string;
  scheduledAt?: string;
  ctid?: string;
}

interface CreateCampaignResp extends RawResp {
  cp_id?: string;
}

async function createCampaign(opts: CreateCampaignOpts): Promise<CreateCampaignResp> {
  const form = new URLSearchParams();
  form.set("name", opts.name);


  form.set("cdlc_id", opts.baseId);
  form.set("content", opts.audioId);
  if (opts.ctid) form.set("cp_ctid", toCtid(opts.ctid));
  form.set("cp_ativo", "1");
  if (opts.scheduledAt) {

    const [d, t] = opts.scheduledAt.split(" ");
    if (d) {
      form.set("date_start", d);
      form.set("date_end", d);
    }
    if (t) form.set("time_start", t);
  }
  const r = await velipPost("/CreateCampaign", form, 30_000);
  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const cp_id = String(env.cp_id ?? env.campaign_id ?? env.id ?? "") || undefined;
  return { ...r, cp_id: cp_id === "0" ? undefined : cp_id };
}

type CampaignAction = "pause" | "resume" | "cancel";

async function changeCampaign(cp_id: string, action: CampaignAction): Promise<RawResp> {
  const form = new URLSearchParams();
  form.set("cp_id", cp_id);


  form.set("active", action === "resume" ? "1" : "0");
  const r = await velipPost("/ChangeCampaign", form, 15_000);

  if (!r.ok && r.status_code === 230) return { ...r, ok: true };
  return r;
}

async function getCampaignsList(): Promise<{ ok: boolean; items: unknown[]; error?: string; raw?: unknown }> {
  const r = await velipPost("/GetCampaignsList", new URLSearchParams(), 15_000);
  const raw = (r.raw ?? {}) as Record<string, unknown>;
  const arr = (raw.campaigns ?? raw.data ?? raw.list ?? []) as unknown[];
  return { ok: r.ok, items: Array.isArray(arr) ? arr : [], error: r.error, raw };
}

interface MakeSMSOpts {
  to: string;
  message: string;
  ctid?: string;
  scheduledAt?: string;

  httpdup?: number;
}

interface MakeSMSResult extends RawResp {
  cdls_id?: string;
}

async function makeSMS(opts: MakeSMSOpts): Promise<MakeSMSResult> {
  const form = new URLSearchParams();
  form.set("dest", opts.to);


  form.set("message", opts.message);
  form.set("cuttext", "1");
  if (opts.ctid) form.set("ctid", toCtid(opts.ctid));
  if (opts.httpdup != null) form.set("httpdup", String(Math.max(0, Math.min(600, opts.httpdup))));

  const r = await velipPost("/MakeSMS", form, 15_000);
  const env = velipEnvelope((r.raw ?? {}) as Record<string, unknown>);
  const cdls_id = String(env.cdls_id ?? env.id ?? "") || undefined;
  const id = cdls_id === "0" ? undefined : cdls_id;


  const waiting = r.status_code === 1 || String(r.status || "").toUpperCase() === "WR";
  const ok = r.ok || (waiting && !!id) || (!!id && (r.status_code === 0 || r.status_code == null));
  return {
    ...r,
    ok,
    cdls_id: id,
    error: ok ? undefined : r.error,
  };
}

async function getCallStatus(cd_id: string): Promise<RawResp & { called_status?: string }> {
  const form = new URLSearchParams();

  form.set("cd_id", cd_id);
  const r = await velipPost("/GetCallStatus", form, 15_000);
  const raw = (r.raw ?? {}) as Record<string, unknown>;

  const calls = Array.isArray(raw.calls) ? (raw.calls as Record<string, unknown>[]) : [];
  const first = calls[0] ?? {};
  const called_status = String(
    first.cd_status ?? first.cd_called_status ?? raw.cd_called_status ?? "",
  ) || undefined;
  return { ...r, called_status };
}

type VelipOutcome =
  | "answered"
  | "no_answer"
  | "invalid_number"
  | "blocked"
  | "do_not_disturb"
  | "nonexistent"
  | "unknown";

function interpretStatus(cd_called_status: string | null | undefined): VelipOutcome {
  const s = String(cd_called_status || "").toUpperCase().trim();
  switch (s) {
    case "OK":
      return "answered";
    case "NA":
      return "no_answer";
    case "EK":
      return "invalid_number";
    case "CK":
      return "blocked";
    case "BK":
      return "do_not_disturb";
    case "IK":
      return "nonexistent";
    default:
      return "unknown";
  }
}

function isRetryable(outcome: VelipOutcome): boolean {
  return outcome === "no_answer";
}

function outcomeToTargetStatus(outcome: VelipOutcome):
  | "completed"
  | "no_answer"
  | "failed"
  | null
{
  switch (outcome) {
    case "answered":
      return "completed";
    case "no_answer":
      return "no_answer";
    case "invalid_number":
    case "blocked":
    case "do_not_disturb":
    case "nonexistent":
      return "failed";
    default:
      return null;
  }
}

function outcomeLabelPtBR(outcome: VelipOutcome): string {
  switch (outcome) {
    case "answered": return "Atendida";
    case "no_answer": return "Não atendeu";
    case "invalid_number": return "Número inválido";
    case "blocked": return "Bloqueio operadora";
    case "do_not_disturb": return "Não perturbe";
    case "nonexistent": return "Número inexistente";
    default: return "Desconhecido";
  }
}

function inCallWindow(cfg: {
  windowStart?: string;
  windowEnd?: string;
  weekdaysOnly?: boolean;
} | null): boolean {
  if (!cfg) return true;
  const now = new Date(Date.now() - 3 * 3600_000);
  if (cfg.weekdaysOnly) {
    const d = now.getUTCDay();
    if (d === 0 || d === 6) return false;
  }
  const start = cfg.windowStart || "09:00";
  const end = cfg.windowEnd || "18:00";
  const [sH, sM] = String(start).split(":").map(Number);
  const [eH, eM] = String(end).split(":").map(Number);
  const startMin = sH * 60 + (sM || 0);
  const endMin = eH * 60 + (eM || 0);
  const cur = now.getUTCHours() * 60 + now.getUTCMinutes();
  if (endMin < startMin) return cur >= startMin || cur <= endMin;
  return cur >= startMin && cur <= endMin;
}

type ContactChannel = "whatsapp" | "voice" | "sms" | "reheat" | "bulk" | "any";

interface ContactSuppressionInput {
  customerId?: string | null;
  phone?: string | null;
  consultantId?: string | null;
  channel?: ContactChannel;
}

interface ContactSuppressionResult {
  allowed: boolean;
  reason: string | null;
  doNotContact: boolean;
  voiceDnc: boolean;
}

function digitsOnly___contact_suppression(phone: string | null | undefined): string {
  return String(phone || "").replace(/\D/g, "");
}

function phonesMatch(a: string, b: string): boolean {
  if (!a || !b) return false;
  if (a === b) return true;
  return a.endsWith(b) || b.endsWith(a);
}

async function assertCanContact(
  supabase: SupabaseClient,
  input: ContactSuppressionInput,
): Promise<ContactSuppressionResult> {
  const channel = input.channel ?? "any";
  const phoneDigits = digitsOnly___contact_suppression(input.phone);
  let doNotContact = false;
  let voiceDnc = false;
  let consultantId = input.consultantId ?? null;

  try {
    if (input.customerId) {
      const { data, error } = await supabase
        .from("customers")
        .select("id, do_not_contact, phone_whatsapp, consultant_id")
        .eq("id", input.customerId)
        .maybeSingle();

      if (error) {
        console.warn("[contact-suppression] customer lookup failed:", error.message);
        return { allowed: false, reason: "lookup_error", doNotContact: true, voiceDnc: false };
      }
      if (!data) {
        return { allowed: false, reason: "customer_not_found", doNotContact: false, voiceDnc: false };
      }
      doNotContact = !!(data as { do_not_contact?: boolean }).do_not_contact;
      consultantId = consultantId || (data as { consultant_id?: string }).consultant_id || null;
      if (!phoneDigits) {
        const wa = digitsOnly___contact_suppression((data as { phone_whatsapp?: string }).phone_whatsapp);
        if (wa) {

          (input as { phone?: string }).phone = wa;
        }
      }
    }

    if (doNotContact) {
      return {
        allowed: false,
        reason: "do_not_contact",
        doNotContact: true,
        voiceDnc: false,
      };
    }


    const phoneForLookup = digitsOnly___contact_suppression(input.phone) || phoneDigits;
    if (!input.customerId && phoneForLookup.length >= 10) {
      const tail = phoneForLookup.slice(-11);
      let q = supabase
        .from("customers")
        .select("id, do_not_contact, phone_whatsapp, consultant_id")
        .eq("do_not_contact", true)
        .ilike("phone_whatsapp", `%${tail}`)
        .limit(10);
      if (consultantId) q = q.eq("consultant_id", consultantId);
      const { data: dncRowsByPhone, error: phoneLookupErr } = await q;
      if (phoneLookupErr) {
        console.warn("[contact-suppression] phone DNC lookup failed:", phoneLookupErr.message);
        return { allowed: false, reason: "lookup_error", doNotContact: true, voiceDnc: false };
      }
      const hit = (dncRowsByPhone ?? []).some((r: { phone_whatsapp?: string }) => {
        const d = digitsOnly___contact_suppression(r.phone_whatsapp);
        return phonesMatch(phoneForLookup, d);
      });
      if (hit) {
        return {
          allowed: false,
          reason: "do_not_contact",
          doNotContact: true,
          voiceDnc: false,
        };
      }
    }

    const checkVoiceDnc = channel === "voice" || channel === "sms" || channel === "reheat" || channel === "any";
    const phoneForDnc = digitsOnly___contact_suppression(input.phone) || phoneDigits;

    if (checkVoiceDnc && consultantId && phoneForDnc) {
      const { data: dncRows, error: voiceDncErr } = await supabase
        .from("voice_dnc_list")
        .select("phone")
        .eq("consultant_id", consultantId);

      if (voiceDncErr) {
        console.warn("[contact-suppression] voice_dnc lookup failed:", voiceDncErr.message);
        return { allowed: false, reason: "lookup_error", doNotContact: false, voiceDnc: true };
      }

      const blocked = (dncRows ?? []).map((r: { phone: string }) => digitsOnly___contact_suppression(r.phone)).filter(Boolean);
      voiceDnc = blocked.some((b) => phonesMatch(phoneForDnc, b));
      if (voiceDnc) {
        return {
          allowed: false,
          reason: "voice_dnc",
          doNotContact: false,
          voiceDnc: true,
        };
      }
    }

    return { allowed: true, reason: null, doNotContact: false, voiceDnc: false };
  } catch (e) {
    console.warn("[contact-suppression] unexpected:", (e as Error)?.message);

    return { allowed: false, reason: "exception", doNotContact: true, voiceDnc: false };
  }
}

async function applyCustomerSuppression(
  supabase: SupabaseClient,
  params: {
    customerId: string;
    consultantId: string;
    phone: string;
    reason?: string;
    channel?: string;
    actorId?: string | null;
    notes?: string | null;
  },
): Promise<{ ok: boolean; error?: string }> {
  const reason = params.reason || "complaint";
  const phone = digitsOnly___contact_suppression(params.phone);
  const now = new Date().toISOString();

  const { error: custErr } = await supabase
    .from("customers")
    .update({
      do_not_contact: true,
      bot_paused: true,
      bot_paused_reason: reason === "complaint" ? "complaint" : "opt_out",
      bot_paused_at: now,
      bot_force_enabled: false,
      attendance_rating_requested_at: null,
      conversation_step: "atendimento_finalizado",
    })
    .eq("id", params.customerId);

  if (custErr) return { ok: false, error: custErr.message };

  if (phone) {
    await supabase.from("voice_dnc_list").upsert(
      {
        consultant_id: params.consultantId,
        phone,
        reason,
        source: "admin_ui",
      },
      { onConflict: "consultant_id,phone" },
    );

    await supabase
      .from("captured_leads")
      .update({ status: "discarded" })
      .eq("consultant_id", params.consultantId)
      .or(`customer_id.eq.${params.customerId},phone.eq.${phone}`);
  }

  await supabase.from("contact_suppression_log").insert({
    customer_id: params.customerId,
    consultant_id: params.consultantId,
    phone: phone || params.phone || "",
    reason,
    channel: params.channel || "admin_ui",
    actor_id: params.actorId ?? null,
    notes: params.notes ?? null,
  });

  return { ok: true };
}

